-- Keep complete Baseball identities for answer reveal while serving only
-- curated symbol artwork during the unanswered question.

-- GENERATED_BASEBALL_SYMBOL_CONTENT_START
on conflict (content_version, item_id) do update set
  display_name = excluded.display_name, asset_path = excluded.asset_path, reveal_asset_path = excluded.reveal_asset_path,
  asset_sha256 = excluded.asset_sha256, source_page_url = excluded.source_page_url, source_asset_url = excluded.source_asset_url,
  rights_status = excluded.rights_status, attribution = excluded.attribution, difficulty = excluded.difficulty, metadata = excluded.metadata;
-- GENERATED_BASEBALL_SYMBOL_CONTENT_END

update public.categories
set current_content_version = 'baseball-symbols-v3'
where id = 'baseball';

-- Rebuild only today's unstarted challenge. Existing ranked attempts retain
-- their immutable content version, round artwork, scores, and timing.
delete from public.daily_challenges challenge
where challenge.category_id = 'baseball'
  and challenge.challenge_date = (timezone('utc', now()))::date
  and not exists (
    select 1
    from public.daily_attempts attempt
    where attempt.challenge_id = challenge.id
  );
